/**
 * useDecoratorConfig Hook
 *
 * This hook manages decorator configuration with proper precedence:
 * - Carousel config (base settings)
 * - Pillar config (override carousel)
 * - Slide config (override pillar)
 * - Style template (suggestion, not override)
 *
 * The hook ensures that decorators are applied consistently across all slides
 * while allowing individual slide customization when needed.
 */

import { useMemo } from 'react';
import { DecoratorConfig, mergeDecoratorConfig, DEFAULT_DECORATOR_CONFIG } from '@/types/decorators';
import { getPillarDecoratorConfig, STYLE_TEMPLATE_DECORATORS } from '@/config/decorators/unified';
import type { PillarId } from '@/types/pillar';

/**
 * Hook parameters
 */
export interface UseDecoratorConfigParams {
  // Carousel-level configuration (optional)
  carouselConfig?: Partial<DecoratorConfig>;

  // Pillar ID
  pillarId: PillarId;

  // Slide-level configuration (optional)
  slideConfig?: Partial<DecoratorConfig>;

  // Style template ID (optional, used as suggestion)
  styleTemplateId?: string;

  // Whether to apply style template suggestions
  applyTemplateSuggestions?: boolean;
}

/**
 * Result of the hook
 */
export interface UseDecoratorConfigResult {
  /**
   * The merged decorator configuration
   */
  config: DecoratorConfig;

  /**
   * The pillar-level configuration (before slide overrides)
   */
  pillarConfig: DecoratorConfig;

  /**
   * The carousel-level configuration (before pillar overrides)
   */
  carouselLevelConfig: DecoratorConfig;

  /**
   * Whether any custom overrides are applied
   */
  hasCustomOverrides: boolean;

  /**
   * Tracks the source of each decorator configuration
   * Helps users understand where each decorator setting comes from
   */
  decoratorSources: {
    /**
     * Decorators set at carousel level
     */
    carousel?: Record<string, boolean>;

    /**
     * Decorators set at pillar level (and not overridden by carousel)
     */
    pillar?: Record<string, boolean>;

    /**
     * Decorators suggested by style template (and not manually configured)
     */
    template?: Record<string, boolean>;

    /**
     * Decorators manually configured at slide level
     */
    slide?: Record<string, boolean>;
  };
}

/**
 * Convert decimal number to Roman numeral
 */
function toRoman(num: number): string {
  const lookup: Record<string, number> = {
    M: 1000,
    CM: 900,
    D: 500,
    CD: 400,
    C: 100,
    XC: 90,
    L: 50,
    XL: 40,
    X: 10,
    IX: 9,
    V: 5,
    IV: 4,
    I: 1,
  };

  let roman = '';
  for (const i in lookup) {
    while (num >= lookup[i]) {
      roman += i;
      num -= lookup[i];
    }
  }
  return roman;
}

/**
 * Convert decimal number to circled number
 */
function toCircled(num: number): string {
  const circled = ['⓪', '①', '②', '③', '④', '⑤', '⑥', '⑦', '⑧', '⑨', '⑩'];
  return circled[num] || num.toString();
}

/**
 * Convert decimal number to squared number
 */
function toSquared(num: number): string {
  const squared = ['⓿', '⓵', '⓶', '⓷', '⓸', '⓹', '⓺', '⓻', '⓼', '⓽', '⓾'];
  return squared[num] || num.toString();
}

/**
 * Format slide number based on style
 */
export function formatSlideNumber(
  number: number,
  style: DecoratorConfig['slideNumber']['style']
): string {
  switch (style) {
    case 'roman':
      return toRoman(number);
    case 'circle':
      return toCircled(number);
    case 'square':
      return toSquared(number);
    case 'decimal':
    case 'minimal':
    case 'pillar-branded':
    default:
      return number.toString();
  }
}

/**
 * Helper to merge decorator config with template suggestions (only where not manually configured)
 */
function mergeWithTemplateSuggestions(
  baseConfig: DecoratorConfig,
  templateSuggestions: Partial<DecoratorConfig>,
  manualConfig: Partial<DecoratorConfig>
): DecoratorConfig {
  const result: DecoratorConfig = { ...baseConfig };

  // Only apply template suggestions where manual config doesn't have that decorator
  Object.keys(templateSuggestions).forEach((key) => {
    const decoratorKey = key as keyof DecoratorConfig;
    if (decoratorKey in manualConfig) {
      // Skip if manually configured at slide level
      return;
    }

    const templateValue = templateSuggestions[decoratorKey];
    if (templateValue) {
      // Apply template suggestion using Object.assign for type safety
      const mergedValue = Object.assign({}, result[decoratorKey], templateValue);
      (result as any)[decoratorKey] = mergedValue;
    }
  });

  return result;
}

/**
 * Hook to compute decorator configuration
 *
 * @param params - Configuration parameters
 * @returns Merged decorator configuration
 */
export function useDecoratorConfig(params: UseDecoratorConfigParams): UseDecoratorConfigResult {
  const {
    carouselConfig,
    pillarId,
    slideConfig,
    styleTemplateId,
    applyTemplateSuggestions = false,
  } = params;

  const result = useMemo(() => {
    // Step 1: Start with default configuration
    let config: DecoratorConfig = { ...DEFAULT_DECORATOR_CONFIG };

    // Step 2: Apply carousel-level configuration (base)
    if (carouselConfig) {
      config = mergeDecoratorConfig(config, carouselConfig);
    }

    // Store carousel-level config for reference
    const carouselLevelConfig = { ...config };

    // Step 3: Apply pillar-level configuration (override carousel)
    const pillarConfig = getPillarDecoratorConfig(pillarId);
    config = mergeDecoratorConfig(config, pillarConfig);

    // Store pillar-level config for reference
    const pillarLevelConfig = { ...config };

    // Step 4: Apply slide-level configuration (override EVERYTHING)
    // This MUST happen before template suggestions
    if (slideConfig) {
      config = mergeDecoratorConfig(config, slideConfig);
    }

    // Step 5: Apply style template suggestions (only where NOT manually configured)
    // Template suggestions are suggestions only, not overrides
    if (applyTemplateSuggestions && styleTemplateId) {
      const templateSuggestion = STYLE_TEMPLATE_DECORATORS[styleTemplateId];
      if (templateSuggestion) {
        // Apply template suggestions only where manual config doesn't exist
        config = mergeWithTemplateSuggestions(config, templateSuggestion, slideConfig || {});
      }
    }

    // Track decorator sources for UI display
    const decoratorSources = {
      carousel: {} as Record<string, boolean>,
      pillar: {} as Record<string, boolean>,
      template: {} as Record<string, boolean>,
      slide: {} as Record<string, boolean>,
    };

    // Track carousel-level decorators
    if (carouselConfig) {
      Object.keys(carouselConfig).forEach((key) => {
        decoratorSources.carousel[key] = true;
      });
    }

    // Track pillar-level decorators (only those not overridden by carousel)
    Object.keys(pillarConfig).forEach((key) => {
      // Only mark as pillar source if not already set by carousel
      if (!decoratorSources.carousel[key]) {
        decoratorSources.pillar[key] = true;
      }
    });

    // Track template-suggested decorators (only those not manually configured)
    if (applyTemplateSuggestions && styleTemplateId) {
      const templateSuggestion = STYLE_TEMPLATE_DECORATORS[styleTemplateId];
      if (templateSuggestion) {
        Object.keys(templateSuggestion).forEach((key) => {
          // Only mark as template source if not manually configured at slide level
          if (!slideConfig || !(key in slideConfig)) {
            decoratorSources.template[key] = true;
          }
        });
      }
    }

    // Track slide-level manually configured decorators
    if (slideConfig) {
      Object.keys(slideConfig).forEach((key) => {
        decoratorSources.slide[key] = true;
      });
    }

    // Determine if custom overrides are applied
    const hasCustomOverrides = Boolean(
      slideConfig ||
      carouselConfig
    );

    return {
      config,
      pillarConfig,
      carouselLevelConfig,
      hasCustomOverrides,
      decoratorSources,
    };
  }, [carouselConfig, pillarId, slideConfig, styleTemplateId, applyTemplateSuggestions]);

  return result;
}

/**
 * Helper hook for getting position styles
 */
export function usePositionStyles(position: string) {
  return useMemo(() => {
    const positions: Record<string, string> = {
      'top-left': 'top-8 left-8',
      'top-right': 'top-8 right-8',
      'bottom-left': 'bottom-8 left-8',
      'bottom-right': 'bottom-8 right-8',
    };
    return positions[position] || 'bottom-8 right-8';
  }, [position]);
}