/**
 * Slide Sub-Types and Positioning System
 *
 * This file defines the type system for:
 * - Element positioning (custom placement and alignment)
 * - Sub-type presets (layout configurations)
 * - Image configuration (image slides with various layouts)
 *
 * @module types/slide-subtypes
 */

// ============================================================================
// ELEMENT POSITIONING SYSTEM
// ============================================================================

/**
 * Positioning mode for an element
 * - auto: Uses existing flexbox behavior, respects container positioning
 * - absolute: Custom X/Y coordinates, independent of container
 * - relative: Offset from auto position, combines auto + custom offset
 */
export type PositionMode = 'auto' | 'absolute' | 'relative';

/**
 * Text alignment options for an element
 */
export type Alignment = 'left' | 'center' | 'right' | 'justify';

/**
 * Element position configuration
 *
 * Defines how an element is positioned within a slide.
 * Supports three positioning modes with varying levels of control.
 */
export interface ElementPosition {
  /**
   * Positioning mode
   * - auto: Standard flexbox behavior
   * - absolute: Custom X/Y coordinates (0-100%)
   * - relative: Offset from auto position
   */
  mode: PositionMode;

  /**
   * Text alignment (for auto and relative modes)
   * Ignored in absolute mode unless specified
   */
  alignment?: Alignment;

  /**
   * X coordinate for absolute positioning (0-100, percentage from left)
   * Only used in absolute mode
   */
  x?: number;

  /**
   * Y coordinate for absolute positioning (0-100, percentage from top)
   * Only used in absolute mode
   */
  y?: number;

  /**
   * Element width as percentage of container (0-100)
   * If not specified, uses default width for element type
   */
  width?: number;

  /**
   * Element height as percentage of container (0-100)
   * If not specified, uses auto height based on content
   */
  height?: number;

  /**
   * Margin top in pixels
   */
  marginTop?: number;

  /**
   * Margin bottom in pixels
   */
  marginBottom?: number;

  /**
   * Margin left in pixels
   */
  marginLeft?: number;

  /**
   * Margin right in pixels
   */
  marginRight?: number;

  /**
   * Z-index for layering
   * Higher values render on top
   * Default layering: background (0) → image (1) → content (10) → decorators (20)
   */
  zIndex?: number;

  /**
   * Offset from top edge in pixels (for relative mode)
   */
  offsetTop?: number;

  /**
   * Offset from bottom edge in pixels (for relative mode)
   */
  offsetBottom?: number;

  /**
   * Offset from left edge in pixels (for relative mode)
   */
  offsetLeft?: number;

  /**
   * Offset from right edge in pixels (for relative mode)
   */
  offsetRight?: number;

  /**
   * Opacity (0-1)
   * Useful for background elements or decorative text
   */
  opacity?: number;

  /**
   * Rotation in degrees (0-360)
   * Useful for decorative elements or effects
   */
  rotation?: number;
}

/**
 * Default element position (auto mode, centered)
 */
export const DEFAULT_ELEMENT_POSITION: ElementPosition = {
  mode: 'auto',
  alignment: 'center',
  marginBottom: 16,
};

// ============================================================================
// STYLE OVERRIDE SYSTEM
// ============================================================================

/**
 * Content style overrides
 *
 * Allows elements to have custom styling that overrides theme defaults.
 * When useTheme is true, theme styling is used. When false, custom styling is used.
 *
 * This enables:
 * - Live theme binding (useTheme: true)
 * - Custom styling overrides (useTheme: false)
 * - Seamless transition between DOM and Canvas modes
 */
export interface ContentStyle {
  /**
   * Font size in pixels
   * If not specified, uses theme default
   */
  fontSize?: number;

  /**
   * Font family name
   * If not specified, uses theme default
   */
  fontFamily?: string;

  /**
   * Font weight (e.g., '400', '700', 'bold')
   * If not specified, uses theme default
   */
  fontWeight?: string;

  /**
   * Text color (hex, rgb, rgba, or named color)
   * If not specified, uses theme default
   */
  color?: string;

  /**
   * Line height (number, e.g., 1.2, 1.5)
   * If not specified, uses theme default
   */
  lineHeight?: number;

  /**
   * Letter spacing in pixels
   * If not specified, uses theme default
   */
  letterSpacing?: number;

  /**
   * Font style ('normal', 'italic')
   * If not specified, uses theme default
   */
  fontStyle?: 'normal' | 'italic';

  /**
   * Text decoration ('none', 'underline', 'line-through')
   * If not specified, uses theme default
   */
  textDecoration?: 'none' | 'underline' | 'line-through';

  /**
   * Whether to use theme styling
   * - true: Use live theme styling (default)
   * - false: Use custom styling overrides
   *
   * When true, theme styling is applied and any custom overrides are ignored.
   * When false, custom styling overrides are used instead of theme styling.
   *
   * This flag is preserved across mode switches and enables live theme binding.
   */
  useTheme?: boolean;
}

/**
 * Default content style (use theme styling)
 */
export const DEFAULT_CONTENT_STYLE: ContentStyle = {
  useTheme: true,
};

/**
 * Positioned content wrapper
 *
 * Allows content to be either a simple value (backward compatible)
 * or an object with value, position, and style configuration.
 *
 * @template T - The type of content value (string, string[], etc.)
 *
 * @example
 * // Backward compatible (string)
 * headline: "My Title"
 *
 * // With positioning
 * headline: {
 *   value: "My Title",
 *   position: {
 *     mode: 'absolute',
 *     x: 50,
 *     y: 20,
 *     alignment: 'center'
 *   }
 * }
 *
 * // With positioning and style overrides (Phase 1)
 * headline: {
 *   value: "My Title",
 *   position: {
 *     mode: 'auto',
 *     alignment: 'center'
 *   },
 *   style: {
 *     fontSize: 72,
 *     color: '#FF0000',
 *     useTheme: false
 *   }
 * }
 */
export type PositionedContent<T> = T | { value: T; position?: ElementPosition; style?: ContentStyle };

/**
 * Helper to check if content has position configuration
 */
export function hasPositionConfig<T>(content: PositionedContent<T>): content is { value: T; position?: ElementPosition } {
  return typeof content === 'object' && content !== null && 'value' in content;
}

/**
 * Helper to get content value from positioned content
 * Maintains backward compatibility by returning the value directly if it's a simple type
 */
export function getContentValue<T>(content: PositionedContent<T> | undefined): T | undefined {
  if (content === undefined) return undefined;
  return hasPositionConfig(content) ? content.value : content;
}

/**
 * Helper to get position configuration from positioned content
 */
export function getContentPosition<T>(content: PositionedContent<T> | undefined): ElementPosition | undefined {
  if (content === undefined) return undefined;
  return hasPositionConfig(content) ? content.position : undefined;
}

/**
 * Helper to get style configuration from positioned content (Phase 1)
 * Returns style overrides if present, otherwise returns default style (useTheme: true)
 */
export function getContentStyle<T>(content: PositionedContent<T> | undefined): ContentStyle | undefined {
  if (content === undefined) return undefined;
  if (!hasPositionConfig(content)) return undefined;
  return (content as any).style;
}

/**
 * Helper to check if content has style overrides (Phase 1)
 */
export function hasStyleConfig<T>(content: PositionedContent<T>): content is { value: T; position?: ElementPosition; style?: ContentStyle } {
  return typeof content === 'object' && content !== null && 'value' in content && 'style' in content;
}

/**
 * Helper to get array value from positioned array content
 * Special handling for arrays to ensure backward compatibility
 */
export function getArrayContent<T>(content: PositionedContent<T[]> | undefined): T[] | undefined {
  if (content === undefined) return undefined;
  return hasPositionConfig(content) ? content.value : content;
}

// ============================================================================
// IMAGE CONFIGURATION SYSTEM
// ============================================================================

/**
 * Object-fit options for image sizing
 */
export type ObjectFit = 'cover' | 'contain' | 'fill' | 'none' | 'scale-down';

/**
 * Image position/layout type
 * Defines how the image is positioned within the slide
 */
export type ImagePosition =
  | 'full-bleed'      // Image covers entire slide, text overlay
  | 'half-left'       // Image 50% left, text 50% right
  | 'half-right'      // Image 50% right, text 50% left
  | 'card'            // Image in centered card with caption
  | 'gradient-overlay'// Image with gradient overlay at bottom for text
  | 'frame'           // Image in decorative frame with text below
  | 'polaroid'        // Polaroid style with caption
  | 'diagonal-split'  // Diagonal split between image and text
  | 'masonry-2'       // 2 images stacked
  | 'masonry-3';      // 3 images in grid

/**
 * Overlay configuration for images
 */
export interface ImageOverlay {
  /**
   * Overlay type
   */
  type: 'none' | 'gradient' | 'solid';

  /**
   * Overlay color (hex or rgba)
   */
  color?: string;

  /**
   * Overlay opacity (0-1)
   */
  opacity?: number;

  /**
   * Gradient direction (for gradient overlay)
   */
  direction?: 'top' | 'bottom' | 'left' | 'right' | 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right';
}

/**
 * Image configuration
 *
 * Defines how an image is displayed in an image slide.
 * Supports various layouts, overlays, and styling options.
 */
export interface ImageConfig {
  /**
   * Image URL
   * Can be absolute URL, relative path, or base64 data URI
   */
  imageUrl: string;

  /**
   * Image position/layout type
   */
  position: ImagePosition;

  /**
   * Image size as percentage of slide (0-100)
   */
  size: number;

  /**
   * Object-fit for image sizing
   */
  objectFit: ObjectFit;

  /**
   * Overlay configuration
   */
  overlay?: ImageOverlay;

  /**
   * Caption text
   */
  caption?: string;

  /**
   * Caption position
   */
  captionPosition?: 'top' | 'bottom' | 'overlay' | 'none';

  /**
   * Border radius in pixels
   */
  borderRadius?: number;

  /**
   * Shadow effect
   */
  shadow?: boolean;

  /**
   * Border around image
   */
  border?: boolean;

  /**
   * Border color
   */
  borderColor?: string;

  /**
   * Border width in pixels
   */
  borderWidth?: number;

  /**
   * Rotation in degrees
   */
  rotation?: number;

  /**
   * Opacity (0-1)
   */
  opacity?: number;

  /**
   * Blend mode for image
   */
  blendMode?: 'normal' | 'multiply' | 'screen' | 'overlay' | 'darken' | 'lighten' | 'color-dodge' | 'color-burn' | 'hard-light' | 'soft-light' | 'difference' | 'exclusion' | 'hue' | 'saturation' | 'color' | 'luminosity';

  /**
   * Filter effects
   */
  filters?: {
    blur?: number;        // Blur radius in pixels
    grayscale?: number;   // 0-1
    sepia?: number;       // 0-1
    saturate?: number;    // 0-2
    brightness?: number;  // 0-2
    contrast?: number;    // 0-2
  };
}

/**
 * Default image configuration
 */
export const DEFAULT_IMAGE_CONFIG: ImageConfig = {
  imageUrl: '',
  position: 'full-bleed',
  size: 100,
  objectFit: 'cover',
  overlay: {
    type: 'none',
  },
  captionPosition: 'none',
  borderRadius: 0,
  shadow: false,
  border: false,
  opacity: 1,
  blendMode: 'normal',
  filters: {},
};

// ============================================================================
// SUB-TYPE SYSTEM
// ============================================================================

/**
 * Import LayoutPosition and StyleTemplateId from styles
 */
import type { LayoutPosition, StyleTemplateId } from './styles';

/**
 * Import SlideType from slide
 */
import type { SlideType } from './slide';

/**
 * Spacing configuration for sub-type
 */
export interface SubTypeSpacing {
  /**
   * Gap between elements in pixels
   */
  elementGap: number;

  /**
   * Gap between sections in pixels
   */
  sectionGap: number;
}

/**
 * Typography defaults for sub-type
 */
export interface SubTypeTypography {
  /**
   * Headline font size (Tailwind class or pixels)
   */
  headlineSize?: string;

  /**
   * Subtext font size (Tailwind class or pixels)
   */
  subtextSize?: string;

  /**
   * Bullet font size (Tailwind class or pixels)
   */
  bulletSize?: string;

  /**
   * Quote font size (Tailwind class or pixels)
   */
  quoteSize?: string;

  /**
   * Attribution font size (Tailwind class or pixels)
   */
  attributionSize?: string;

  /**
   * Font weight
   */
  fontWeight?: string;

  /**
   * Line height
   */
  lineHeight?: string;
}

/**
 * Layout configuration for sub-type
 */
export interface SubTypeLayout {
  /**
   * Container position
   */
  containerPosition: LayoutPosition;

  /**
   * Container max width as percentage (50-100)
   */
  containerMaxWidth: number;

  /**
   * Spacing configuration
   */
  spacing: SubTypeSpacing;
}

/**
 * Default element positions for sub-type
 * Each key corresponds to a content field in SlideContent
 */
export interface SubTypeDefaults {
  /**
   * Headline position
   */
  headline?: ElementPosition;

  /**
   * Subtext position
   */
  subtext?: ElementPosition;

  /**
   * Bullets position
   */
  bullets?: ElementPosition;

  /**
   * Quote position
   */
  quote?: ElementPosition;

  /**
   * Attribution position
   */
  attribution?: ElementPosition;

  /**
   * CTA text position
   */
  ctaText?: ElementPosition;

  /**
   * Image position
   */
  image?: ElementPosition;

  /**
   * CTA button position
   */
  ctaButton?: ElementPosition;
}

/**
 * Slide sub-type configuration
 *
 * Defines a preset layout configuration for a specific slide type.
 * Includes default element positions, layout configuration, and typography defaults.
 */
export interface SlideSubType {
  /**
   * Unique sub-type identifier
   * Format: {slideType}-{subTypeName}
   * Example: "title-classic", "image-full-bleed"
   */
  id: string;

  /**
   * Human-readable name
   */
  name: string;

  /**
   * Description of this sub-type
   */
  description: string;

  /**
   * Parent slide type
   */
  slideType: SlideType;

  /**
   * Optional thumbnail image URL
   * For displaying in sub-type selector UI
   */
  thumbnail?: string;

  /**
   * Default element positions
   * Applied when this sub-type is selected
   */
  defaults: SubTypeDefaults;

  /**
   * Layout configuration
   */
  layout: SubTypeLayout;

  /**
   * Typography defaults
   * Overrides default template typography
   */
  typography?: SubTypeTypography;

  /**
   * Compatible style templates
   * If not specified, compatible with all templates
   */
  compatibleWith?: StyleTemplateId[];

  /**
   * Tags for filtering/searching
   */
  tags?: string[];

  /**
   * Whether this is the default sub-type for its slide type
   */
  isDefault?: boolean;
}

/**
 * Helper to check if sub-type is compatible with a style template
 */
export function isSubTypeCompatible(subType: SlideSubType, templateId: StyleTemplateId): boolean {
  if (!subType.compatibleWith || subType.compatibleWith.length === 0) {
    return true; // Compatible with all templates
  }
  return subType.compatibleWith.includes(templateId);
}

/**
 * Helper to get default sub-type for a slide type
 */
export function getDefaultSubTypeForSlideType(slideType: SlideType): string {
  const defaults: Record<SlideType, string> = {
    title: 'title-classic',
    content: 'content-standard',
    bullets: 'bullets-vertical',
    quote: 'quote-classic',
    cta: 'cta-standard',
    custom: 'content-standard',
    image: 'image-full-bleed',
  };
  return defaults[slideType] || `${slideType}-standard`;
}

// ============================================================================
// UTILITY TYPES
// ============================================================================

/**
 * Slide content with positioned elements
 * Extends SlideContent to support positioned content for all fields
 */
export interface PositionedSlideContent {
  headline?: PositionedContent<string>;
  subtext?: PositionedContent<string>;
  bullets?: PositionedContent<string[]>;
  quote?: PositionedContent<string>;
  attribution?: PositionedContent<string>;
  ctaText?: PositionedContent<string>;
  imageUrl?: string; // Deprecated, use imageConfig instead
  imageConfig?: ImageConfig;
}

/**
 * Mapped content types for type inference
 */
export type ContentFieldType = 'headline' | 'subtext' | 'bullets' | 'quote' | 'attribution' | 'ctaText';

/**
 * Position configuration map
 * Maps content field names to their position configurations
 */
export type PositionConfigMap = Partial<Record<ContentFieldType, ElementPosition>>;